Property.Value:
BEGIN
    DECLARE @BonusPercent DECIMAL(5, 2);

    SET @BonusPercent = CASE
        WHEN @Department = 'Engineering' THEN 15.00
        WHEN @Department = 'Product'     THEN 12.00
        WHEN @Department = 'DevOps'      THEN 13.00
        ELSE 10.00
    END;

    RETURN @Salary * @BonusPercent / 100.00;
END;

CREATE FUNCTION [dbo].[fn_CalculateBonus]
(
    @Salary     DECIMAL(18, 2),
    @Department NVARCHAR(50)
)
RETURNS DECIMAL(18, 2)
AS

BEGIN SET NOCOUNT ON;
-- Log INSERTs INSERT INTO [dbo].[AuditLog] ([TableName], [Operation], [RecordID], [NewValues]) SELECT 'SchemaEvolutionDemo', 'INSERT', i.[ID], CONCAT('Name=', i.[Name], '|Dept=', i.[Department], '|Status=', i.[Status]) FROM inserted i WHERE NOT EXISTS (SELECT 1 FROM deleted d WHERE d.[ID] = i.[ID]);
-- Log DELETEs INSERT INTO [dbo].[AuditLog] ([TableName], [Operation], [RecordID], [OldValues]) SELECT 'SchemaEvolutionDemo', 'DELETE', d.[ID], CONCAT('Name=', d.[Name], '|Dept=', d.[Department], '|Status=', d.[Status]) FROM deleted d WHERE NOT EXISTS (SELECT 1 FROM inserted i WHERE i.[ID] = d.[ID]);
-- Log UPDATEs INSERT INTO [dbo].[AuditLog] ([TableName], [Operation], [RecordID], [OldValues], [NewValues]) SELECT 'SchemaEvolutionDemo', 'UPDATE', i.[ID], CONCAT('Name=', d.[Name], '|Dept=', d.[Department], '|Status=', d.[Status]), CONCAT('Name=', i.[Name], '|Dept=', i.[Department], '|Status=', i.[Status]) FROM inserted i INNER JOIN deleted d ON i.[ID] = d.[ID]; END;
